package ai.taskforge.api; import ai.taskforge.repo.AuditLogRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/audit-logs") @PreAuthorize("hasRole('ADMIN')") public class AuditController { private final AuditLogRepository logs;public AuditController(AuditLogRepository l){logs=l;} record View(UUID id,String actor,String action,String entityType,UUID entityId,String oldValue,String newValue,java.time.Instant createdAt){} @GetMapping List<View> list(){return logs.findAll().stream().sorted(Comparator.comparing(x->x.getCreatedAt(),Comparator.reverseOrder())).map(x->new View(x.getId(),x.getActor()==null?"System":x.getActor().getDisplayName(),x.getAction(),x.getEntityType(),x.getEntityId(),x.getOldValue(),x.getNewValue(),x.getCreatedAt())).toList();} }
